def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    if nanoseconds is None:
        return None
    try:
        n = int(nanoseconds)
    except (TypeError, ValueError):
        raise TypeError("nanoseconds must be an integer or convertible to int")
    if n < 0:
        raise ValueError("nanoseconds must be non‑negative")
    seconds, ns = divmod(n, 1_000_000_000)
    micro = ns // 1000
    import datetime
    if tz is None:
        dt = datetime.datetime.utcfromtimestamp(seconds)
    else:
        if hasattr(tz, "utcoffset") and callable(tz.utcoffset):
            dt = datetime.datetime.fromtimestamp(seconds, tz)
        else:
            raise TypeError("tz must be a datetime.tzinfo instance")
    dt = dt.replace(microsecond=micro)
    return dt.time()

