def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    # Handle None
    if value is None:
        return None

    # Attempt to handle datetime.time objects
    try:
        from datetime import time as _dt_time
        if isinstance(value, _dt_time):
            return value.isoformat()
    except Exception:
        pass

    # If the object provides an isoformat method, use it
    if hasattr(value, 'isoformat') and callable(value.isoformat):
        try:
            return value.isoformat()
        except Exception:
            pass

    # If it provides a strftime method, format as HH:MM:SS
    if hasattr(value, 'strftime') and callable(value.strftime):
        try:
            return value.strftime('%H:%M:%S')
        except Exception:
            pass

    # Fallback: cast to string, raising TypeError for non-stringible types
    try:
        return str(value)
    except Exception as exc:
        raise TypeError("Value of type %s cannot be dehydrated to a time string" % type(value).__name__) from exc

