def dehydrate_point(value):
    """ Dehydrator for Point data.
    Converts a Point-like object (e.g. shapely.geometry.Point) into a simple
    tuple that can be serialized.  The function accepts objects that expose
    numeric `x` and `y` attributes (or `lon`/`lat` as a fall‑back), and
    optionally a `z` attribute.  If `value` is ``None`` the function returns
    ``None``.
    """
    if value is None:
        return None

    # Try to fetch x,y from common attribute names
    try:
        x = getattr(value, "x")
        y = getattr(value, "y")
    except AttributeError:
        try:
            x = getattr(value, "lon")
            y = getattr(value, "lat")
        except AttributeError:
            raise TypeError(
                "Expected a Point-like object with numeric 'x'/'y' or "
                "'lon'/'lat' attributes"
            )

    # Basic type validation
    if not isinstance(x, (int, float)) or not isinstance(y, (int, float)):
        raise TypeError("Point coordinates must be numeric values")

    z = getattr(value, "z", None)
    if z is not None and not isinstance(z, (int, float)):
        raise TypeError("Point 'z' coordinate must be a numeric value if present")

    return (x, y) if z is None else (x, y, z)

