def values(self, *keys):
    """
    Return the values of the record, optionally filtering to include only
    certain values by index or key.

    :param keys: indexes or keys of the items to include; if none are
                 provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Obtain the underlying data structure.
    # Prefer a ``data`` attribute if present, otherwise fall back to
    # the instance's ``__dict__``.  We also attempt to treat any iterable
    # of (key, value) pairs as a fallback.

    if hasattr(self, "data") and isinstance(self.data, (dict, list)):
        content = self.data
    else:
        content = getattr(self, "__dict__", {})

    # Normalise to a list of (key, value) pairs.
    try:
        if isinstance(content, dict):
            items = list(content.items())
        else:
            # Assume an iterable of (key, value) tuples.
            items = list(content)
            if not all(isinstance(it, tuple) and len(it) == 2 for it in items):
                raise TypeError
    except Exception:
        raise TypeError("record object has no accessible key/value pairs")

    # If no keys provided, return all values.
    if not keys:
        return [val for _, val in items]

    # Select the requested values.
    result = []
    for key in keys:
        if isinstance(key, int):
            # Index-based access.
            try:
                # Handle negative indices naturally.
                _, val = items[key]
                result.append(val)
            except IndexError as exc:
                raise IndexError(f"index {key} out of range") from exc
        else:
            # Key-based access – find the first matching key.
            for k, val in items:
                if k == key:
                    result.append(val)
                    break
            else:
                raise KeyError(f"key {key!r} not found")
    return result

