def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
        """Appends a DISCARD message to the output queue."""
        # Accept no hooks by default
        if dehydration_hooks is None:
            dehydration_hooks = {}
        if hydration_hooks is None:
            hydration_hooks = {}

        # Basic validation of n and qid
        if not isinstance(n, int):
            raise TypeError("n must be an integer")
        if not isinstance(qid, int):
            raise TypeError("qid must be an integer")

        # Build a message dict (protocol specific)
        msg = {"command": "DISCARD", "n": n, "qid": qid}

        # Try to pack the message using the instance's pack method,
        # falling back to the raw dict if packing is unavailable.
        try:
            packed = self._pack_message(
                msg,
                dehydration=dehydration_hooks,
                hydration=hydration_hooks
            )
        except AttributeError:
            packed = msg

        # Append to the instance's output queue (create if absent)
        output_queue = getattr(self, "_output_queue", [])
        output_queue.append(packed)
        setattr(self, "_output_queue", output_queue)

        # Return a Response object, passing any handlers
        return Response(output_queue, handlers)

