def deprecated(message):
    """Decorator for deprecating functions and methods.

    Usage (note the parentheses around the message string in the decorator):
        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass
    """
    if not isinstance(message, str):
        raise ValueError("Deprecated decorator requires a message string")
    def decorator(func):
        import warnings
        from functools import wraps
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Emit a DeprecationWarning with the provided message.
            # Using stacklevel=2 ensures the warning points to the caller of the deprecated function.
            warnings.warn(f"{func.__name__} is deprecated: {message}",
                          DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

