def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import subprocess
    import concurrent.futures
    import os
    import sys

    # Helper: compute approximate command line length
    def _cmd_len(base: Sequence[str], args: Sequence[str]) -> int:
        # approximate: sum of lengths plus spaces
        return sum(len(x) for x in base + args) + len(base) + len(args) - 1

    # Build batches of arguments respecting _max_length
    batches: list[list[str]] = []
    current: list[str] = []
    for arg in varargs:
        tentative_len = _cmd_len(cmd, current + [arg])
        if tentative_len > _max_length and current:
            batches.append(current)
            current = [arg]
        else:
            current.append(arg)
    if current:
        batches.append(current)

    # If no arguments, still run the command once
    if not batches:
        batches = [[]]

    # Function to run a single batch
    def _run_batch(batch: list[str]) -> tuple[int, bytes]:
        try:
            result = subprocess.run(
                list(cmd) + batch,
                capture_output=True,
                **kwargs
            )
            return result.returncode, result.stdout
        except OSError as e:
            # Return non-zero code and error message as bytes
            return 1, str(e).encode()

    # Decide whether to use a pty for color
    use_pty = False
    if color and sys.stdout.isatty():
        try:
            import pty
            use_pty = True
        except ImportError:
            use_pty = False

    # Run batches concurrently
    retcode = 0
    outputs = []

    with concurrent.futures.ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        future_to_batch = {
            executor.submit(
                _run_batch, batch
            ): idx for idx, batch in enumerate(batches)
        }
        for future in concurrent.futures.as_completed(future_to_batch):
            code, out = future.result()
            if code != 0:
                retcode = code
            outputs.append(out)

    # Return combined exit code and concatenated output
    return retcode, b"".join(outputs)

