            return key + kw

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            if key in cache:
                value, count = cache[key]
                cache[key] = (value, count + 1)
                return value
            # Cache miss
            result = func(*args, **kwargs)
            if len(cache) >= maxsize:
                # Find least frequently used key (tie broken by first occurrence)
                min_count = None
