def reset(self):
        """Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        # Reset the context dictionary
        self.context = {}

        # Re‑initialize the bins
        try:
            if hasattr(self, "initial_value") and self.initial_value is not None:
                # If an initial value was supplied, replicate it across all existing bins
                if hasattr(self, "bins"):
                    self.bins = [self.initial_value for _ in self.bins]
                else:
                    # No bins currently exist – create a default list of one element
                    self.bins = [self.initial_value]
            else:
                # No explicit initial value – generate fresh bins using make_bins
                if hasattr(self, "make_bins") and callable(self.make_bins):
                    self.bins = self.make_bins()
                else:
                    # Fallback: clear bins if make_bins is missing
                    self.bins = []
        except Exception as exc:
            raise RuntimeError(f"Failed to reset histogram bins: {exc}") from exc

