def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    try:
        bins = list(bins)
    except TypeError:
        raise TypeError("bins must be an iterable of numeric values")
    try:
        edges = list(edges)
    except TypeError:
        raise TypeError("edges must be an iterable of numeric values")

    if len(edges) != len(bins) + 1:
        raise ValueError("Number of edges must be one more than number of bins")

    total = 0.0
    for bi, e0, e1 in zip(bins, edges, edges[1:]):
        width = e1 - e0
        if width < 0:
            raise ValueError("edges must be monotonically increasing")
        try:
            total += float(bi) * width
        except Exception as exc:
            raise TypeError("bins must contain numeric values") from exc

    return float(total)

