def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Directly check if the object itself is the desired type
    if isinstance(seq, FillRequest):
        return True

    # A Source sequence is disallowed – the object itself should not be Source
    if isinstance(seq, Source):
        return False

    # Strings (including bytes) should not be treated as an element sequence
    if isinstance(seq, (str, bytes)):
        return False

    # Attempt to iterate over seq; if not iterable return False
    try:
        iterator = iter(seq)
    except TypeError:
        return False

    has_fill = False
    all_source = True
