def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present
    """
    # Basic sanity checks
    if not isinstance(last_applied_manifest, list):
        raise TypeError("last_applied_manifest must be a list")
    if not isinstance(observer_schema, list):
        raise TypeError("observer_schema must be a list")
    if not isinstance(response, list):
        raise TypeError("response must be a list")

    # Extend last_applied_manifest to match observer_schema length if necessary
    if len(last_applied_manifest) < len(observer_schema):
        last_applied_manifest.extend([None] * (len(observer_schema) - len(last_applied_manifest)))

    for idx, obs in enumerate(observer_schema):
        # Skip if observer element is explicitly None or undefined
        if obs is None:
            continue

        if idx >= len(response):
            # No corresponding response element; nothing to update
            continue
        resp = response[idx]

        # Retrieve current value in last_applied_manifest
        curr = last_applied_manifest[idx]

        # Decide how to update based on the type of the observer element
        if isinstance(obs, dict):
            # Expect a dict in the response
            if isinstance(resp, dict):
                # Ensure we have a dict to update
                if not isinstance(curr, dict):
                    curr = {}
                # Recursively update nested dictionaries
                update_last_applied_manifest_dict_from_resp(curr, obs, resp)
                last_applied_manifest[idx] = curr
            else:
                # Mismatch: just replace with the response value
                last_applied_manifest[idx] = resp

        elif isinstance(obs, list):
            # Expect a list in the response
            if isinstance(resp, list):
                if not isinstance(curr, list):
                    curr = []
                # Recursively update nested lists
                update_last_applied_manifest_list_from_resp(curr, obs, resp)
                last_applied_manifest[idx] = curr
            else:
                last_applied_manifest[idx] = resp

        else:
            # Primitive observed field
            if curr is None:
                last_applied_manifest[idx] = resp
    # No explicit return: the function modifies last_applied_manifest in place.

