        """Return string of validator status, with optional prefix."""
        parts = []

        # Include a primary status attribute if it exists
        if hasattr(self, 'status'):
            status_val = self.status
            if status_val:
                parts.append(str(status_val))

        # Gather secondary status-related attributes (errors, warnings, info)
        for attr in ('errors', 'warnings', 'info'):
            if hasattr(self, attr):
                values = getattr(self, attr)
                if values:
                    if isinstance(values, (list, tuple)):
                        for v in values:
                            parts.append(f'{attr}: {str(v)}')
                    else:
                        parts.append(f'{attr}: {str(values)}')

        # If no status information is available, return an empty prefixed string
        if not parts:
            return prefix

        # Prefix each line and join with newline characters
        prefixed_lines = [f'{prefix}{line}' for line in parts]
        return '\n'.join(prefixed_lines)

