def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        # Basic sanity checks
        if inventory is None:
            raise ValueError("No inventory provided for validation")

        if not isinstance(inventory, dict):
            raise TypeError("Inventory must be a dictionary-like object")

        # Determine spec version
        spec_version = self.spec_version  # default
        if extract_spec_version:
            typ = inventory.get("type")
            if typ is not None:
                if isinstance(typ, str):
                    spec_version = typ
                else:
                    raise ValueError("Inventory 'type' must be a string if present")
            # else: keep default spec_version and continue

        # Define minimal required keys depending on spec_version
        required_keys = {"id", "docs", "spec_version"}
        if spec_version == "legacy":
            required_keys.add("compatibility")

        # Validate presence of required keys
        missing = required_keys - inventory.keys()
        if missing:
            raise ValueError(f"Inventory missing required keys: {', '.join(sorted(missing))}")

        # Basic value checks
        if not isinstance(inventory["id"], str) or not inventory["id"]:
            raise ValueError("Inventory 'id' must be a non-empty string")

        if not isinstance(inventory["docs"], list) or not inventory["docs"]:
            raise ValueError("Inventory 'docs' must be a non-empty list")

        if not isinstance(inventory["spec_version"], str):
            raise ValueError("Inventory 'spec_version' must be a string")

        # Additional checks for legacy spec
        if spec_version == "legacy":
            if "compatibility" not in inventory or not isinstance(inventory["compatibility"], dict):
                raise ValueError("Legacy inventory must contain a 'compatibility' dict")

        # All checks passed
        return True

