def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if version is None:
        raise ValueError("version must not be None")

    mapping = {}
    # Try to get entries directly keyed by version
    try:
        entries = inventory.get(version, [])
    except AttributeError:
        # inventory might be a list or iterable of entries
        entries = [e for e in inventory if getattr(e, "version", None) == version]

    for entry in entries:
        # Retrieve logical path
        logical = None
        if isinstance(entry, dict):
            logical = entry.get("logical_path")
            content = entry.get("content_file")
        else:
            logical = getattr(entry, "logical_path", None)
            content = getattr(entry, "content_file", None)

        if logical is None or content is None:
            continue

        if not isinstance(logical, str):
            # Skip non-string logical paths
            continue

        mapping.setdefault(logical, set()).add(content)

    return mapping

