    """Add an asset file to the current element.

    Args:
        basename (str): The key (usually the base name including extension) to be used
            for the asset.  Must be a non-empty string.
        file_path (str): The absolute or relative path to the asset file that
            should be associated with this element.

    Raises:
        ValueError: If *basename* or *file_path* are not non‑empty strings.
        FileNotFoundError: If *file_path* does not exist or is not a file.
        KeyError: If an asset with the same *basename* is already present.
    """
    # Validate the arguments
    if not isinstance(basename, str) or not basename:
        raise ValueError("basename must be a non‑empty string")
    if not isinstance(file_path, str) or not file_path:
        raise ValueError("file_path must be a non‑empty string")

    # Ensure that the file exists
    try:
        import os
        if not os.path.isfile(file_path):
            raise FileNotFoundError(f"File not found: {file_path}")
    except ImportError:
        # Fallback to pathlib if os is not available
        from pathlib import Path
        if not Path(file_path).is_file():
            raise FileNotFoundError(f"File not found: {file_path}")

    # Initialise or update the assets mapping
    if hasattr(self, 'assets') and isinstance(self.assets, dict):
        if basename in self.assets:
            raise KeyError(f"An asset with basename '{basename}' already exists")
        self.assets[basename] = file_path
    else:
        self.assets = {basename: file_path}

