def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path

    Returns
    -------
    dict
    """
    import os
    import zipfile

    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for info in zf.infolist():
                # Skip directories
                if info.is_dir() if hasattr(info, "is_dir") else info.filename.endswith('/'):
                    continue
                name = info.filename
                try:
                    data = zf.read(name)
                except Exception:
                    # Skip unreadable files
                    continue
                base = os.path.splitext(os.path.basename(name))[0]
                if base not in result:
                    result[base] = {}
                result[base][name] = data
    except FileNotFoundError as e:
        raise FileNotFoundError(f"The zip file '{zip_path}' was not found.") from e
    except zipfile.BadZipFile as e:
        raise zipfile.BadZipFile(f"The file '{zip_path}' is not a valid zip file.") from e

    return result

