def pretty(self, indent=0, debug=False):
        """Return a pretty formatted representation of self."""
        # Validate indent
        if not isinstance(indent, int) or indent < 0:
            raise TypeError("indent must be a non‑negative integer")

        def _serialize(obj, level):
            """Recursively serialize an object into an indented string."""
            # Use explicit pretty if available
            if hasattr(obj, "pretty") and callable(obj.pretty):
                return obj.pretty(indent=level, debug=debug)

            # Represent dictionaries nicely
            if isinstance(obj, dict):
                items = []
                for k, v in obj.items():
                    items.append(f"{_serialize(k, 0)}: {_serialize(v, 0)}")
                return f"{{{', '.join(items)}}}"

            # Represent sequences by items
            if isinstance(obj, (list, tuple, set)):
                items = [_serialize(item, level + 2) for item in obj]
                brackets = ("[", "]") if isinstance(obj, list) else ("(", ")") if isinstance(obj, tuple) else ("{", "}")
                return f"{brackets[0]}{', '.join(items)}{brackets[1]}"

            # Fallback to string representation
            return str(obj)

        # Build the representation of this object
        lines = []
        indent_str = " " * indent
        lines.append(f"{indent_str}{self.__class__.__name__}:")
        # Include attributes if they exist
        attrs = getattr(self, "__dict__", {})
        # Pretty debug: show internal dict
        if debug and attrs:
            lines.append(f"{indent_str}  <attributes>")
            for key, value in sorted(attrs.items()):
                lines.append(f"{indent_str}    {key} = {_serialize(value, indent + 4)}")
            lines.append(f"{indent_str}  </attributes>")
        # Pretty children
        children = None
        if hasattr(self, "children"):
            children = getattr(self, "children")
        elif hasattr(self, "content"):
            children = getattr(self, "content")
        if children:
            for child in children:
                if child is not None:
                    lines.append(_serialize(child, indent + 2))
        return "\n".join(lines)

