def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2.

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings.
    """
    import sys

    def _wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        if result is None:
            return None
        # In Python 2, make sure we return a byte string
        if sys.version_info[0] < 3:
            try:
                # If result is unicode, encode it; if already bytes, return as-is
                if hasattr(result, "encode"):
                    return result.encode("utf-8")
                return result
            except Exception:
                # Fall back to raw result if encoding fails
                return result
        # Python 3 and later: return result unchanged
        return result

    return _wrapper

