        # Fallback for older Python versions using the compatibility package
        try:
            from importlib_metadata import metadata  # type: ignore
            version = metadata.version(pkg_name)
        except Exception:
            # If all attempts fail, keep the default 'unknown'
            pass

    # Return a dictionary mapping the package name to its detected version
    return {pkg_name: version}

