def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Basic validation
    if style is None:
        raise ValueError("Requested style cannot be None")
    if not isinstance(style, str):
        raise TypeError(f"Style must be a string, got {type(style).__name__}")

    # Ensure pieces is iterable
    try:
        iterator = iter(pieces)
    except TypeError:
        raise TypeError(f"Pieces must be an iterable, got {type(pieces).__name__}")

    rendered_parts = []

    for idx, piece in enumerate(iterator):
        if piece is None:
            continue  # skip null pieces gracefully

        # If the piece has a render method, use it
        if hasattr(piece, "render") and callable(piece.render):
            try:
                rendered = piece.render(style)
            except Exception as exc:
                raise RuntimeError(f"Error rendering piece #{idx} ({type(piece).__name__}) with style '{style}': {exc}") from exc
        else:
            # Fallback: convert to string
            rendered = str(piece)

        rendered_parts.append(rendered)

    return "".join(rendered_parts)

