        """Call the given command(s)."""
        # Validate input and build the command
        if isinstance(commands, str):
            # Combine the command string with args if provided
            if args:
                cmd_str = f"{commands} {' '.join(map(str, args))}"
            else:
                cmd_str = commands
            use_shell = True
            cmd = cmd_str
        else:
            if not isinstance(commands, (list, tuple)):
                raise TypeError("commands must be a string or list/tuple of program and arguments")
            cmd = [str(c) for c in commands]
            if args:
                cmd.extend(map(str, args))
            use_shell = False

        if not cmd:
            raise ValueError("No command provided to run")

        # Execute the command
        try:
            if verbose:
                print(f"Running command: {cmd if isinstance(cmd, str) else ' '.join(cmd)}")
            result = subprocess.run(
                cmd,
                shell=use_shell,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
            )
            # Handle stdout and stderr based on flags
            if verbose and result.stdout:
                print(result.stdout, end='')
            if not hide_stderr and result.stderr:
                print(result.stderr, file=sys.stderr, end='')
            result.check_returncode()
            return result
        except subprocess.CalledProcessError as exc:
            # Re-raise to allow caller to handle it
            raise exc
        except Exception as exc:
            raise RuntimeError(f"Failed to run command '{cmd}': {exc}") from exc

