def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # stack based traversal to avoid recursion limits
    stack = [self]
    while stack:
        obj = stack.pop()
        if obj is None:
            continue

        num_objects += 1
        valid = True

        # validate object properties if requested
        if validate_objects:
            try:
                # some objects might expose `is_valid()` or `validate()`
                if hasattr(obj, 'is_valid') and callable(obj.is_valid):
                    valid = bool(obj.is_valid())
                elif hasattr(obj, 'validate') and callable(obj.validate):
                    valid = bool(obj.validate())
                # if neither method exists, we assume it is valid
            except Exception as exc:
                valid = False
                if show_warnings:
                    print(f"Warning: Validation of object {obj!r} raised exception: {exc}")

        # check digests if requested
        if valid and check_digests:
            try:
                # some objects might expose `check_digest()` or `digest_valid`
                if hasattr(obj, 'check_digest') and callable(obj.check_digest):
                    valid = bool(obj.check_digest())
                elif hasattr(obj, 'digest_valid') and callable(obj.digest_valid):
                    valid = bool(obj.digest_valid())
                # if no method, we leave valid unchanged
            except Exception as exc:
                valid = False
                if show_warnings:
                    print(f"Warning: Digest check for object {obj!r} raised exception: {exc}")

        if valid:
            good_objects += 1
        elif show_warnings:
            print(f"Warning: Object {obj!r} failed validation checks.")

        # enqueue child objects
        children = None
        if hasattr(obj, 'children'):
            children = obj.children
        elif hasattr(obj, 'get_children') and callable(obj.get_children):
            try:
                children = obj.get_children()
            except Exception:
                children = None
        elif hasattr(obj, '__iter__') and not isinstance(obj, (str, bytes)):
            try:
                children = list(obj)
            except Exception:
                children = None

        if children:
            try:
                stack.extend(children)
            except Exception:
                # if children is not iterable, skip
                pass

    return num_objects, good_objects

