def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if isinstance(version, int):
        return str(version + 1)

    if not isinstance(version, str):
        raise ValueError(f"Unsupported version type: {type(version)}")

    if not version.isdigit():
        raise ValueError(f"Version must be a numeric string: {version}")

    # Count leading zeros
    leading_zeros = len(version) - len(version.lstrip('0'))
    base_value = int(version)
    new_value = base_value + 1

    # Preserve length if there was a non-zero prefix or leading zeros
    if leading_zeros > 0 and len(version) > 1:
        return str(new_value).zfill(len(version))
    return str(new_value)

