def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import json

    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory paths")

    # Ensure we have an attribute to store differences; create if missing
    if not hasattr(self, 'different_digests'):
        self.different_digests = {}

    cumulative_files = set()
    root_inventory = None

    for idx, vdir in enumerate(version_dirs, start=1):
        if not os.path.isdir(vdir):
            raise ValueError(f"Version directory '{vdir}' does not exist or is not a directory")

        # Determine inventory file; allow common formats
        inv_path_json = os.path.join(vdir, "inventory.json")
        inv_path_xml = os.path.join(vdir, "inventory.xml")

        if os.path.exists(inv_path_json):
            inv_format = "json"
            inv_path = inv_path_json
        elif os.path.exists(inv_path_xml):
            inv_format = "xml"
            inv_path = inv_path_xml
        else:
            raise ValueError(f"No inventory file found in '{vdir}' (expected inventory.json or inventory.xml)")

        try:
            if inv_format == "json":
                with open(inv_path, "r", encoding="utf-8") as f:
                    inventory = json.load(f)
                # Expected structure: dict of filename -> digest
                if not isinstance(inventory, dict):
                    raise ValueError(f"Inventory in {inv_path} is not a JSON object")
            else:
                # Minimal XML parsing using ElementTree for <file> elements
                import xml.etree.ElementTree as ET
                tree = ET.parse(inv_path)
                root = tree.getroot()
                inventory = {}
                for file_elem in root.findall(".//file"):
                    name = file_elem.get("name")
                    digest = file_elem.get("digest")
                    if name is None or digest is None:
                        continue
                    inventory[name] = digest
        except Exception as e:
            raise ValueError(f"Failed to parse inventory in '{inv_path}': {e}") from e

        # Set the root inventory from the first version
        if idx == 1:
            root_inventory = inventory.copy()
        else:
            # Ensure current inventory contains all items from cumulative set
            missing = cumulative_files - set(inventory.keys())
            if missing:
                raise ValueError(f"Inventory in version {idx} '{vdir}' is missing files that were present in earlier versions: {missing}")

            # Compare digests with root inventory
            for fname, digest in inventory.items():
                if fname in root_inventory and root_inventory[fname] != digest:
                    self.different_digests.setdefault(fname, []).append(
                        (root_inventory[fname], digest)
                    )

        # Update cumulative set for next iteration
        cumulative_files.update(inventory.keys())

    return self.different_digests

