def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Ensure parameters are in expected format
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if not bug_ids:
        # Nothing to amend – return the original dictionary
        return params

    # Normalise bug_ids to a list of integers
    if isinstance(bug_ids, (str, bytes)):
        # Split a comma‑separated string into individual ids
        ids_list = [bid.strip() for bid in bug_ids.split(',') if bid.strip()]
    else:
        try:
            # Try iterating over the supplied object
            ids_list = list(bug_ids)
        except TypeError:
            raise TypeError("bug_ids must be an iterable of ids")

    cleaned = []
    for bid in ids_list:
        try:
            cleaned.append(int(bid))
        except (ValueError, TypeError):
            # Non‑numeric ids are skipped
            continue

    if not cleaned:
        return params

    # Merge with any existing 'ids' entry in params
    existing = params.get("ids")
    if existing is not None:
        if isinstance(existing, (list, tuple)):
            cleaned = list(existing) + cleaned
        else:
            cleaned.append(existing)

    params["ids"] = cleaned
    return params

