def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    """
    # Helper to identify mapping nodes without importing ruamel.yaml explicitly
    def _is_mapping(node):
        return hasattr(node, "value") and isinstance(node.value, list) and getattr(node, "tag", "").startswith("tag:yaml.org,2002:map")

    def _merge_mapping(a, b):
        """
        a and b are MappingNodes. Return a new MappingNode whose mapping is the deep merge
        of a and b, preferring values from b on conflicts.
        """
        # Build dict from mapping a
        merged = {}
        for a_key, a_val in a.value:
            key = a_key.value
            merged[key] = (a_key, a_val)
        # Merge with mapping b
        for b_key, b_val in b.value:
            key = b_key.value
            if key in merged:
                _, a_val = merged[key]
                merged[key] = (_merge_node(a_val, b_val))
            else:
                merged[key] = (b_key, b_val)
        # Reconstruct mapping list preserving order from the dict
        new_value = [merged[k] for k in merged]
        return a.__class__(tag=b.tag, value=new_value)

    def _merge_node(a, b):
        """
        Recursively merge two nodes a and b.
        If both are mapping nodes, merge their content;
        otherwise, return b (last wins).
        """
        if _is_mapping(a) and _is_mapping(b):
            return _merge_mapping(a, b)
        # If one is mapping and the other is not, let b override
        return b

    result_map = {}
    result_order = []

    for key_node, val_node in nodes:
        # Use key string for comparison; ScalarNode should have .value attribute
        key_str = getattr(key_node, "value", None)
        if key_str is None:
            raise ValueError("Key node is not a ScalarNode with a 'value' attribute")
        if key_str in result_map:
            # Merge existing value with new value
            existing_key_node, existing_val_node = result_map[key_str]
            merged_val = _merge_node(existing_val_node, val_node)
            result_map[key_str] = (existing_key_node, merged_val)
        else:
            # First occurrence
            result_map[key_str] = (key_node, val_node)
            result_order.append(key_str)

    # Build ordered list of tuples
    merged_nodes = [(result_map[k][0], result_map[k][1]) for k in result_order]
    return merged_nodes

