        raise TypeError(f"max_results must be an integer, got {type(max_results).__name__}")
    if max_results <= 0:
        raise ValueError(f"max_results must be positive, got {max_results}")

    # Ensure the response is list-like; try to convert if it isn't a sequence
    try:
        # Accept any iterable that supports slicing (list, tuple, etc.)
        length = len(response)
    except Exception:
        # Attempt to convert to list if possible
        try:
            response = list(response)
        except Exception as e:
            raise TypeError("response must be an iterable of items") from e

    # Yield paginated slices
    for start in range(0, len(response), max_results):
        yield response[start:start + max_results]

