def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    import re
    from urllib.parse import quote

    # If there are no arguments given, simply return the URL unchanged
    if not url_args:
        return url

    # Decide which lookup style to use based on type of url_args
    if isinstance(url_args, (list, tuple)):
        # Positional indexing: placeholders must be integers {0}, {1}, etc.
        def _repl(match):
            key = match.group(1)
            if not key.isdigit():
                raise ValueError(
                    f"Invalid placeholder '{key}' for positional args; "
                    "use integer indices like {{0}}, {{1}}, ..."
                )
            idx = int(key)
            if idx >= len(url_args):
                raise IndexError(
                    f"Index {idx} out of range in URL args list (len={len(url_args)})"
                )
            return quote(str(url_args[idx]), safe="")

    elif isinstance(url_args, dict):
        # Named dictionary lookup: placeholders are key names {name}
        def _repl(match):
            key = match.group(1)
            if key not in url_args:
                raise KeyError(f"Missing URL argument: {key}")
            return quote(str(url_args[key]), safe="")

    else:
        raise TypeError("url_args must be a dict, list, or tuple")

    # Perform the substitution
    pattern = r"{([^{}]+)}"
    if re.search(pattern, url):
        return re.sub(pattern, _repl, url)
    return url

