def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Basic validation: ensure the object behaves like a argparse.ArgumentParser
    if not hasattr(parser, '_actions'):
        raise TypeError("Expected an argparse.ArgumentParser instance or object with an '_actions' attribute")

    flags = []
    for action in parser._actions:
        # Only consider optional arguments that have flags
        if getattr(action, 'option_strings', None):
            flags.extend(action.option_strings)

    return ' '.join(flags)

