    if not isinstance(register_value, str):
        raise TypeError(f"register_value must be a str, got {type(register_value).__name__}")

    def _recursively_replace(obj):
        if isinstance(obj, dict):
            for k, v in obj.items():
                if k == register_value:
                    obj[k] = register_number
                # recurse into nested structures
                if isinstance(v, (dict, list)):
                    _recursively_replace(v)
        elif isinstance(obj, list):
            for item in obj:
                _recursively_replace(item)

    _recursively_replace(flow_params)
    return flow_params

