def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("The argument must be a class.")
    # Use a local helper to avoid duplicates in diamond inheritance scenarios
    seen = set()

    def _collect(c):
        for sub in c.__subclasses__():
            if sub not in seen:
                seen.add(sub)
                yield sub
                yield from _collect(sub)

    return list(_collect(cls))

