def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    # If frequency is None or represents 'always', return None
    if frequency is None:
        return None
    freq = str(frequency).strip().lower()
    if freq == 'always':
        return None

    import re
    # Regex to capture the number and the time unit
    match = re.match(r'^(\d+)\s*(\w+)$', freq)
    if not match:
        raise ValueError(f"Frequency '{frequency}' is not in the expected format '<number> <unit>'")

    number_str, unit = match.groups()
    try:
        number = int(number_str)
    except ValueError:
        raise ValueError(f"Invalid numeric value in frequency '{frequency}'")

    # Mapping units to timedelta keyword arguments or functions converting to timedelta
    if unit in ('day', 'days'):
        return datetime.timedelta(days=number)
    elif unit in ('week', 'weeks'):
        return datetime.timedelta(weeks=number)
    elif unit in ('hour', 'hours'):
        return datetime.timedelta(hours=number)
    elif unit in ('minute', 'minutes'):
        return datetime.timedelta(minutes=number)
    elif unit in ('second', 'seconds'):
        return datetime.timedelta(seconds=number)
    elif unit in ('month', 'months'):
        # Approximate a month as 30 days
        return datetime.timedelta(days=30 * number)
    elif unit in ('year', 'years'):
        # Approximate a year as 365 days
        return datetime.timedelta(days=365 * number)
    else:
        raise ValueError(f"Unsupported time unit '{unit}' in frequency '{frequency}'")

