def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not isinstance(host, str):
        return False
    host = host.strip()
    # Quick checks for common localhost aliases
    localhost_aliases = {'localhost', '127.0.0.1', '::1'}
    if host.lower() in localhost_aliases:
        return True
    try:
        # Resolve host to addresses
        for res in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = res
            ip = sockaddr[0]
            if family in (socket.AF_INET, socket.AF_INET6):
                if ip in ('127.0.0.1', '::1'):
                    return True
    except (socket.gaierror, socket.herror, socket.timeout, OSError):
        # If resolution fails, assume not local
        return False
    return False

