def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    if not isinstance(matcher, str):
        raise TypeError('matcher must be a string')
    matcher = matcher.strip()
    if not matcher:
        raise ValueError('Empty matcher string provided')
    if '=' in matcher:
        name, _, default = matcher.partition('=')
        name = name.strip()
        default = default.strip()
        if not name:
            raise ValueError('Environment variable name is missing in matcher')
        value = os.environ.get(name)
        if value is None:
            return default
        return value
    else:
        name = matcher
        value = os.environ.get(name)
        if value is None:
            raise ValueError(f"Environment variable '{name}' not set and no default value provided")
        return value

