def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""

    # Use a dedicated Dumper or default to yaml.SafeDumper
    if dumper is None:
        dumper = yaml.SafeDumper

    # Perform the dump with unicode support
    try:
        # If the dumper supports allow_unicode we set it to True
        dump_kwargs = dict(Dumper=dumper, default_flow_style=False, allow_unicode=True)
    except Exception:
        dump_kwargs = dict(default_flow_style=False)

    try:
        result = yaml.dump(obj, **dump_kwargs)
    except TypeError:
        # Fallback to safe_dump if kwargs not accepted
        result = yaml.safe_dump(obj, default_flow_style=False, allow_unicode=True)

    # Ensure we return a string type appropriate for Python 2 or 3
    if isinstance(result, bytes):
        # In Python 2 yaml.dump may return a byte string, decode it
        try:
            result = result.decode("utf-8")
        except Exception:
            # If decoding fails, return raw string
            pass

    return result

