    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Normalise shape to a tuple
    if isinstance(shape, int):
        shape_tuple = (shape,)
    else:
        try:
            shape_tuple = tuple(shape)
        except Exception as exc:
            raise ValueError("Shape must be an integer or iterable of integers") from exc

    # Validate all dimensions are non‑negative integers
    if not all(isinstance(dim, int) and dim >= 0 for dim in shape_tuple):
        raise ValueError("All dimensions in shape must be non‑negative integers")

    # Resolve dtype to a numpy dtype object
    try:
        np_dtype = np.dtype(dtype)
    except Exception as exc:
        raise TypeError("dtype must be convertible to a numpy dtype") from exc

    return np.zeros(shape_tuple, dtype=np_dtype)

