def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    from collections.abc import Sequence, Iterator, Iterable
    # Handle ``None`` explicitly
    if seq is None:
        return (None, None)

    # Preserve file-like objects by reading them entirely
    if hasattr(seq, "read") and callable(seq.read):
        try:
            # Read whole content; honour ``bufsize`` if provided
            if bufsize is None:
                data = seq.read()
            else:
                chunks = []
                while True:
                    chunk = seq.read(bufsize)
                    if not chunk:
                        break
                    chunks.append(chunk)
                data = b"".join(chunks) if isinstance(chunks[0], (bytes, bytearray)) else "".join(chunks)
            seq = data
        except Exception:
            # Fallback: treat as iterator below
            pass

    # If seq itself is a sequence (string, bytes, list, tuple, array etc.), use it directly
    if isinstance(seq, Sequence) and not isinstance(seq, (str, bytes, bytearray)):
        # For string/bytes, we treat them as immutable sequences but still return them
        pass

    # If seq is not a basic sequence type, try to materialise it
    if not isinstance(seq, (str, bytes, bytearray)) and not isinstance(seq, Sequence):
        # Iterable but not a sequence
        if isinstance(seq, (Iterator, Iterable)):
            try:
                seq = list(seq)
            except Exception:
                # As a last resort, leave it unchanged
                pass

    return (seq, type(seq))

