def scale(self, other=None, recompute=False):
        """Compute or set scale (integral of the histogram).

        If *other* is ``None``, return scale of this histogram.
        If its scale was not computed before,
        it is computed and stored for subsequent use
        (unless explicitly asked to *recompute*).
        Note that after changing (filling) the histogram
        one must explicitly recompute the scale
        if it was computed before.

        If a float *other* is provided, rescale self to *other*.

        Histograms with scale equal to zero can't be rescaled.
        :exc:`.LenaValueError` is raised if one tries to do that.
        """
        # Helper to compute the integral from the underlying bins
        def _compute():
            # Common attribute names for bin counts
            if hasattr(self, "values"):
                vec = self.values
            elif hasattr(self, "_values"):
                vec = self._values
            elif hasattr(self, "bins"):
                vec = self.bins
            elif hasattr(self, "_bins"):
                vec = self._bins
            else:
                raise ValueError("Histogram has no recognizable bin attribute")
            return float(sum(vec))

        if other is None:
            # Getter: return cached value if available and recompute flag is False
            if not recompute and hasattr(self, "_scale") and self._scale is not None:
                return self._scale
            # Compute fresh
            self._scale = _compute()
            return self._scale

        # Setter: rescale to a new numeric value
        if not isinstance(other, (int, float)):
            raise TypeError(f"Expected numeric value for scaling, got {type(other)}")
        new_scale = float(other)

        # Retrieve current scale (force recompute to avoid stale value)
        current_scale = _compute()
        if current_scale == 0.0:
            if new_scale != 0.0:
                # Cannot rescale a zero-scale histogram to a non‑zero value
                raise LenaValueError(
                    "Cannot rescale histogram with zero scale to a non‑zero target."
                )
            # Setting to zero: zero out all bins
            if hasattr(self, "values"):
                self.values = [0] * len(self.values)
            elif hasattr(self, "_values"):
                self._values = [0] * len(self._values)
            elif hasattr(self, "bins"):
                self.bins = [0] * len(self.bins)
            elif hasattr(self, "_bins"):
                self._bins = [0] * len(self._bins)
            self._scale = 0.0
            return self

        # Scale factor required to achieve desired new_scale
        factor = new_scale / current_scale

        # Apply factor to all bin counts
        if hasattr(self, "values"):
            self.values = [v * factor for v in self.values]
        elif hasattr(self, "_values"):
            self._values = [v * factor for v in self._values]
        elif hasattr(self, "bins"):
            self.bins = [v * factor for v in self.bins]
        elif hasattr(self, "_bins"):
            self._bins = [v * factor for v in self._bins]
        else:
            # If we can't find the bin container we can't perform rescaling
            raise ValueError("Histogram has no recognizable bin attribute for rescaling")

        # Update cached scale
        self._scale = new_scale
        return self

