    """Format a datetime in the way that D* nodes expect."""
    if dt is None:
        return None
    # Ensure we have a datetime; convert date to datetime at midnight
    if hasattr(dt, 'year') and hasattr(dt, 'month') and hasattr(dt, 'day'):
        if hasattr(dt, 'hour'):
            d = dt
        else:
            # Assume it's a date
            d = datetime.combine(dt, datetime.min.time())
    else:
        raise TypeError("format_dt expects a date or datetime object")
    # If naive, assume UTC
    if d.tzinfo is None:
        d = d.replace(tzinfo=datetime.timezone.utc)
    # Convert to UTC (in case tzinfo is not UTC) and format
    utc = d.astimezone(datetime.timezone.utc)
    return utc.strftime('%Y-%m-%dT%H:%M:%SZ')

