def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # Ensure input is a string
    if not isinstance(tag, str):
        return False

    # Tags must not be empty and must not contain leading/trailing whitespace
    if not tag or tag.strip() != tag:
        return False

    # Tags may contain letters, digits, hyphens and underscores only, and must start with a letter or digit
    # They must not start or end with a hyphen or underscore.
    # Example: "foo-bar_1" is valid; "_foo" or "foo-" are invalid.
    if not tag[0].isalnum() or not tag[-1].isalnum():
        return False

    for ch in tag:
        if not (ch.isalnum() or ch in ('-', '_')):
            return False

    return True

