def verify_relayable_signature(public_key, doc, signature):
    """Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message."""
    from lxml import etree
    import xmlsec

    # Validate inputs
    if public_key is None:
        raise ValueError("public_key must be provided")
    if doc is None:
        raise ValueError("doc must be provided")
    if signature is None:
        raise ValueError("signature must be provided")

    # Parse the document if it is a string
    if isinstance(doc, str):
        try:
            doc_tree = etree.fromstring(doc.encode("utf-8"))
        except Exception as exc:
            raise ValueError("doc could not be parsed as XML") from exc
    else:
        # Assume an lxml element or ElementTree
        doc_tree = doc if isinstance(doc, etree._Element) else doc.getroot()

    # Find the existing Signature node in the document or construct one from the string
    try:
        sig_node = xmlsec.tree.find_node(doc_tree, xmlsec.constants.NodeSignature)
        if sig_node is None:
            # Build a Signature node from the provided string
            try:
                sig_node = etree.fromstring(signature.encode("utf-8"))
            except Exception as exc:
                raise ValueError("signature string could not be parsed as XML") from exc
    except Exception as exc:
        raise ValueError("Failed to locate or construct a Signature node") from exc

    # Prepare verification context
    ctx = xmlsec.SignatureContext()
    try:
        # Normalize public key input
        if isinstance(public_key, (bytes, bytearray)):
            key_data = public_key
        else:
            key_data = public_key.encode("utf-8")

        key = xmlsec.Key.from_memory(key_data, xmlsec.KeyFormat.PEM, None)
        ctx.key = key
    except Exception as exc:
        raise ValueError("Failed to load public key") from exc

    # Register Id attributes so the context can resolve references
    try:
        ctx.register_id(doc_tree, "Id")
    except Exception:
        # If no Id attribute is used, ignore it
        pass

    # Perform verification
    try:
        ctx.verify(sig_node)
    except xmlsec.VerificationError as exc:
        raise ValueError("Signature verification failed") from exc
    except Exception as exc:
        raise ValueError("An unexpected error occurred during verification") from exc

    return True

