def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Try JSON parsing first
    try:
        import json
        result = json.loads(document)
        if not isinstance(result, dict):
            raise ValueError("JSON webfinger must be a JSON object")
        return result
    except json.JSONDecodeError:
        pass  # fallback to XML

    # Parse as XRD (XML)
    try:
        import xml.etree.ElementTree as ET
    except Exception as exc:
        raise ValueError("Required XML parser not available") from exc

    try:
        root = ET.fromstring(document)
    except ET.ParseError as exc:
        raise ValueError("Invalid XML format for XRD webfinger") from exc

    def strip_ns(tag):
        return tag.split('}', 1)[-1] if '}' in tag else tag

    result: Dict[str, object] = {}
    aliases = []
    links = []

    for child in root:
        tag = strip_ns(child.tag)
        if tag == 'Subject':
            result['subject'] = child.text.strip() if child.text else ''
        elif tag == 'Alias':
            if child.text:
                aliases.append(child.text.strip())
        elif tag == 'Link':
            link_info: Dict[str, str] = {}
            # include attributes
            for k, v in child.attrib.items():
                link_info[k] = v
            # also check subelements for href maybe
            href_elem = child.find('*')
            # Not necessary; attributes likely contain href
            links.append(link_info)

    if aliases:
        result['aliases'] = aliases
    if links:
        result['links'] = links

    return result

