def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import requests

    try:
        # Ensure we have a scheme
        if not host.startswith(('http://', 'https://')):
            base = 'https://' + host
        else:
            base = host

        # Common URLs used by Diaspora for host-meta discovery
        urls = [
            base.rstrip('/') + '/.well-known/host-meta',
            base.rstrip('/') + '/.well-known/host-meta.pub',
            'http://' + host.rstrip('/') + '/.well-known/host-meta',
        ]

        headers = {'Accept': 'application/xrd+xml'}
        for url in urls:
            try:
                response = requests.get(url, headers=headers, timeout=5, allow_redirects=True)
                if response.status_code == 200:
                    content = response.content
                    # Try the static-length parsing method first, fall back to
                    # string-based parsing if needed.
                    try:
                        # If XRD can be constructed with bytes
                        return XRD(content)
                    except Exception:
                        return XRD(content.decode('utf-8'))
            except Exception:
                # Non-fatal for this URL, try the next
                continue

        raise ValueError(f"Could not retrieve a host-meta document from host: {host}")

    except Exception as exc:
        raise ValueError(f"Error retrieving host-meta from {host}: {exc}") from exc

