def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    # Basic validation
    if not isinstance(dic, dict):
        raise TypeError("'dic' must be a dict instance")
    if not isinstance(key, (str, int, float, bool, tuple, frozenset)):
        raise TypeError("Key must be a hashable type")
    for k in keys:
        if not isinstance(k, (str, int, float, bool, tuple, frozenset)):
            raise TypeError("All keys must be hashable types")

    # Build the full key chain
    chain = [key] + list(keys)
    if not chain:
        raise ValueError("At least one key must be supplied")

    # Traverse/create nested dictionaries for all but the last key
    current = dic
    for k in chain[:-1]:
        if k in current:
            if not isinstance(current[k], dict):
                # If the existing value is not a dict, replace it with a new dict
                current[k] = {}
        else:
            current[k] = {}
        current = current[k]

    # Insert the value at the last key
    current[chain[-1]] = val
    return dic

