def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Allow the include directive to merge nested group definitions.
    # The directive may appear directly in the dictionary being parsed or
    # nested inside a 'groups' key.  We return a new dictionary that
    # contains the merged result to avoid mutating the caller's data.
    if not isinstance(parser_dict, dict):
        return parser_dict

    resolved = {}
    # First handle top‑level include key if present
    include = parser_dict.get("include")
    if include is not None:
        # `include` can be a dict, a list of dicts or a single dict.
        if isinstance(include, dict):
            include_items = [include]
        elif isinstance(include, list):
            include_items = [item for item in include if isinstance(item, dict)]
        else:
            include_items = []

        for inc_dict in include_items:
            for k, v in inc_dict.items():
                # prefer already existing keys unless they are missing
                if k not in resolved:
                    resolved[k] = v

    # Now iterate over the remaining items
    for key, value in parser_dict.items():
        if key == "include":
            # already processed
            continue
        if isinstance(value, dict):
            resolved[key] = self._include_groups(value)
        else:
            resolved[key] = value

    return resolved

