def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    spec = getattr(self, 'spec', None)
    if not spec:
        return defaults

    # The spec is expected to contain an 'args' mapping of argument names
    # to dictionaries that may contain default values, environment
    # variable names, or other metadata.
    args_spec = spec.get('args', {})
    if not isinstance(args_spec, dict):
        # If args_spec is not a dict, we cannot interpret defaults
        return defaults

    import os
    for arg, config in args_spec.items():
        # Ensure config is a dict to avoid attribute errors
        if not isinstance(config, dict):
            continue

        # 1. Check for an overridden value in an environment variable
        env_name = config.get('env')
        if env_name:
            env_val = os.getenv(env_name)
            if env_val is not None:
                defaults[arg] = env_val
                continue

        # 2. Use the default defined in the spec
        if 'default' in config:
            val = config['default']
            # Support callables that compute a default value lazily
            if callable(val):
                try:
                    val = val()
                except Exception:
                    # If the callable fails, fallback to None
                    val = None
            defaults[arg] = val

    return defaults

