def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from CLI
    :param answer_file_args: the dict of arguments from files
    """
    # Basic type checking
    if cli_args is None:
        cli_args = {}
    if answer_file_args is None:
        answer_file_args = {}
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Retrieve declared deprecated arguments (expected to be a dict mapping old names to new names)
    deprecated_map = getattr(self, "DEPRECATED_ARGS", {})
    if not isinstance(deprecated_map, (dict, set, list, tuple)):
        raise TypeError("DEPRECATED_ARGS must be a dict, set, list or tuple")

    # Normalise the deprecated map to a dictionary if it's a sequence
    if isinstance(deprecated_map, (set, list, tuple)):
        deprecated_map = {arg: None for arg in deprecated_map}

    # Collect warning messages
    warnings = []

    for source_name, source_args in (("CLI", cli_args), ("Answer file", answer_file_args)):
        for key, value in source_args.items():
            if key in deprecated_map:
                replacement = deprecated_map[key]
                replacement_text = f" (use '{replacement}')".replace("'None'", "") if replacement else ""
                warnings.append(f"{source_name} argument '{key}' is deprecated{replacement_text}.")

    # Print any warnings
    for w in warnings:
        print(w)

