def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    # Ensure options_spec is iterable
    try:
        option_iterable = iter(options_spec)
    except TypeError:
        raise TypeError("options_spec must be an iterable of option definitions")

    matched = []

    # Prepare evaluation context - include args and command_name
    eval_context = {}
    if isinstance(args, dict):
        eval_context.update(args)
    else:
        # If args is not dict, expose it under the name 'args'
        eval_context['args'] = args
    eval_context['command_name'] = command_name

    for opt in option_iterable:
        if not isinstance(opt, dict):
            continue  # skip non-dict entries

        # Determine option name/key
        opt_name = opt.get("name") or opt.get("id") or opt.get("key") or opt.get("option")
        if not opt_name:
            continue

        required_when = opt.get("required_when")
        if required_when is None:
            continue

        # Handle callable conditions
        if callable(required_when):
            try:
                condition_met = bool(required_when(args))
            except Exception:
                # If callable throws an error, treat as False
                condition_met = False
        # Handle string expressions
        elif isinstance(required_when, str):
            try:
                # Use eval in context; raise if key not found
                condition_met = bool(eval(required_when, {}, eval_context))
            except Exception:
                condition_met = False
        else:
            # Unsupported type; skip
            continue

        if condition_met:
            matched.append(opt_name)

    return matched

