def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict")

    # Optional per-argument maximum lengths can be defined in self.max_lengths
    max_lengths = getattr(self, "max_lengths", {})

    for key, value in args.items():
        if key not in max_lengths:
            continue  # No length restriction for this argument

        max_len = max_lengths[key]
        if value is None:
            continue  # None is allowed regardless of length

        try:
            length = len(value)
        except TypeError:
            raise TypeError(f"Argument '{key}' does not support len()")

        if length > max_len:
            raise ValueError(
                f"Argument '{key}' has length {length}, "
                f"exceeds maximum allowed length of {max_len}"
            )
    return True

