def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Get the mapping of choice arguments to their allowed values.
    # Most element classes expose a ``CHOICES`` class attribute mapping
    # attribute names to a set/list of allowed values. If the attribute
    # is missing we simply treat there are no restrictions.
    choices = getattr(self.__class__, 'CHOICES', {})

    # If ``choices`` is a list of tuples or similar, normalise it to a
    # dictionary for fast lookup.
    if isinstance(choices, (list, tuple)):
        choices = {k: v for k, v in choices if isinstance(k, str)}

    for name, value in args.items():
        # Skip arguments that are not declared as choice arguments.
        if name not in choices:
            continue

        # Skip if ``value`` is None – the caller is signalling the
        # attribute is not present.
        if value is None:
            continue

        allowed = choices[name]
        # ``allowed`` might be a set, tuple, list, or a single string.
        if isinstance(allowed, (set, list, tuple)):
            if value not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{name}': {value!r}. "
                    f"Allowed values are: {sorted(allowed)}."
                )
        else:
            # ``allowed`` is a single value; treat it as the only
            # acceptable choice.
            if value != allowed:
                raise ValueError(
                    f"Invalid value for argument '{name}': {value!r}. "
                    f"Only value allowed is {allowed!r}."
                )
    return True  # success indicator

