    min_args = getattr(self, "min_args", None)
    max_args = getattr(self, "max_args", None)

    if min_args is not None and count < min_args:
        raise ValueError(
            f"Too few arguments: expected at least {min_args}, got {count}."
        )

    if max_args is not None and count > max_args:
        raise ValueError(
            f"Too many arguments: expected at most {max_args}, got {count}."
        )

    # All checks passed
    return True

