    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    if args is None:
        return control_args, nested_args

    # Determine if args is a mapping or an iterable of key/value pairs
    if isinstance(args, dict):
        items = args.items()
    else:
        try:
            # Accept any iterable of two-item sequences
            items = iter(args)
        except TypeError as exc:
            raise TypeError("args must be a mapping or an iterable of key-value pairs") from exc

    for item in items:
        if isinstance(args, dict):
            key, value = item
        else:
            if not isinstance(item, (list, tuple)) or len(item) != 2:
                # Skip malformed entries gracefully
                continue
            key, value = item

        if not isinstance(key, str):
            # Only string keys are processed
            continue

        # Define control arguments as those prefixed with '_' or starting with 'control'
        lower_key = key.lower()
        if key.startswith('_') or lower_key.startswith('control'):
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

