    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: Extra variables to add.  Can be a ``dict``,
            a list/tuple of ``(key, value)`` tuples, or a list of
            ``"key=value"`` strings.  ``None`` is ignored.
        """
        if not isinstance(vars_dict, dict):
            raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

        if extra_vars is None:
            return vars_dict

        # dict: simply update
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
            return vars_dict

        # iterable of pairs or strings
        try:
            iterator = iter(extra_vars)
        except TypeError:
            raise TypeError(f"extra_vars must be a dict or an iterable, got {type(extra_vars).__name__}")

        for item in iterator:
            # If the item itself is a dict, treat as dict of pairs
            if isinstance(item, dict):
                vars_dict.update(item)
                continue

            # If item is a tuple/list of two elements
            if isinstance(item, (tuple, list)) and len(item) == 2:
                key, value = item
                if not isinstance(key, str):
                    raise ValueError(f"Key must be a string, got {type(key).__name__}")
                vars_dict[key] = value
                continue

            # If item is a string "key=value"
            if isinstance(item, str):
                if "=" not in item:
                    raise ValueError(f"String item must contain '=', got '{item}'")
                key, value = item.split("=", 1)
                if not key:
                    raise ValueError(f"Empty key in string item '{item}'")
                vars_dict[key] = value
                continue

            # If none of the above
            raise ValueError(f"Unsupported item type {type(item).__name__} in extra_vars")

        return vars_dict

