def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import json
    from pathlib import Path

    try:
        import yaml  # type: ignore
    except ImportError as e:
        raise ImportError("PyYAML is required to parse plugin specs: " + str(e))

    # Resolve to Path object
    p_dir = Path(plugin_dir).expanduser().resolve()
    if not p_dir.is_dir():
        raise FileNotFoundError(f"Plugin directory {plugin_dir} does not exist or is not a directory")

    # Try finding the spec file
    spec_files = [
        p_dir / "plugin_spec.json",
        p_dir / "plugin_spec.yml",
        p_dir / "plugin_spec.yaml",
        p_dir / "metadata.json",
        p_dir / "metadata.yml",
        p_dir / "metadata.yaml",
    ]

    spec_path = None
    for sf in spec_files:
        if sf.is_file():
            spec_path = sf
            break

    if spec_path is None:
        raise FileNotFoundError(
            f"No plugin spec file found in {plugin_dir}. "
            f"Expected one of: {', '.join(str(f.name) for f in spec_files)}"
        )

    # Load the spec content
    try:
        with spec_path.open("r", encoding="utf-8") as f:
            if spec_path.suffix in {".json"}:
                spec_data = json.load(f)
            else:
                spec_data = yaml.safe_load(f)
    except (json.JSONDecodeError, yaml.YAMLError) as exc:
        raise ValueError(f"Failed to parse plugin spec file {spec_path}: {exc}") from exc

    if not isinstance(spec_data, dict):
        raise TypeError(f"Plugin spec top-level element must be a mapping, got {type(spec_data).__name__}")

    # Helper to flatten nested dict / list structures
    def _flatten(prefix, obj, acc):
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_prefix = f"{prefix}.{k}" if prefix else str(k)
                _flatten(new_prefix, v, acc)
        elif isinstance(obj, (list, tuple)):
            for idx, item in enumerate(obj):
                new_prefix = f"{prefix}[{idx}]" if prefix else f"[{idx}]"
                _flatten(new_prefix, item, acc)
        else:
            acc[prefix] = obj

    flat_dict: dict[str, object] = {}
    _flatten("", spec_data, flat_dict)

    return flat_dict

