def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    config_env = 'CONFIG_PATH'
    if os.getenv(config_env) is None:
        if hasattr(self, 'config_path'):
            path = getattr(self, 'config_path')
            if not isinstance(path, str):
                raise TypeError("config_path must be a string")
            os.environ[config_env] = path
        else:
            raise AttributeError("Object has no 'config_path' attribute to set environment variable")

